-- ============================================================================
-- SafarSync — Supabase / PostgreSQL schema
-- Ported from lib/backend/safarsync_complete_migration.sql (+ migration_v10..v16)
--
-- Conversion notes (MySQL → PostgreSQL)
--   INT AUTO_INCREMENT      → integer GENERATED BY DEFAULT AS IDENTITY
--   TINYINT(1)              → boolean
--   ENUM(...)               → text + CHECK constraint
--   JSON                    → jsonb
--   DECIMAL(p,s)            → numeric(p,s)
--   TIMESTAMP / DATETIME    → timestamptz
--   ON UPDATE CURRENT_TIMESTAMP → BEFORE UPDATE trigger (public.set_updated_at)
--   FULLTEXT index          → GIN trigram index (pg_trgm)
--
-- Identity: users.user_id stays an integer (the Flutter UI compares integer ids
-- everywhere). Each row is linked to Supabase Auth via users.auth_user_id.
-- Legacy-only tables (Traveler, `destination`) are folded into users /
-- destinations and not recreated.
-- ============================================================================

create extension if not exists pg_trgm with schema extensions;

-- ── updated_at helper ───────────────────────────────────────────────────────
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ============================================================================
-- Core entities
-- ============================================================================

create table public.users (
  user_id                  integer generated by default as identity primary key,
  auth_user_id             uuid unique references auth.users(id) on delete cascade,
  email                    text not null unique,
  full_name                text not null,
  phone_number             text,
  city                     text,
  profile_picture_url      text,
  blood_group              text,
  bio                      text,
  auth_provider            text not null default 'EMAIL'
                           check (auth_provider in ('EMAIL','GOOGLE','APPLE','FACEBOOK')),
  role                     text not null default 'user',
  is_active                boolean not null default true,
  is_admin                 boolean not null default false,
  is_blocked               boolean not null default false,
  suspended_at             timestamptz,
  suspended_reason         text,
  last_login_at            timestamptz,
  theme_preference         text not null default 'default'
                           check (theme_preference in ('default','snow','desert','beach','mountain','forest','urban')),
  -- formerly the legacy Traveler table's "last location" columns
  last_location            text,
  last_latitude            numeric(10,8),
  last_longitude           numeric(11,8),
  last_location_updated_at timestamptz,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz
);
create index idx_users_is_admin      on public.users (is_admin);
create index idx_users_is_blocked    on public.users (is_blocked);
create index idx_users_created_at    on public.users (created_at desc);
create index idx_users_city          on public.users (city);
create trigger trg_users_updated before update on public.users
  for each row execute function public.set_updated_at();

-- Admin accounts (separate role table; authentication itself is Supabase Auth)
create table public.admins (
  admin_id      integer generated by default as identity primary key,
  auth_user_id  uuid unique references auth.users(id) on delete set null,
  email         text not null unique,
  full_name     text not null,
  role          text not null default 'moderator' check (role in ('super_admin','moderator')),
  is_active     boolean not null default true,
  last_login    timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz
);
create trigger trg_admins_updated before update on public.admins
  for each row execute function public.set_updated_at();

create table public.destinations (
  destination_id      integer generated by default as identity primary key,
  name                text not null,
  description         text,
  latitude            numeric(10,8),
  longitude           numeric(11,8),
  location            text,
  city                text,
  country             text,
  category            text,
  image_url           text,
  rating              numeric(3,2),
  review_count        integer not null default 0,
  popularity_score    integer not null default 0,
  weather_data        jsonb,
  best_time_to_visit  text,
  average_cost        numeric(10,2),
  price_label         text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz
);
create index idx_dest_city_country on public.destinations (city, country);
create index idx_dest_category     on public.destinations (category);
create index idx_dest_name_trgm    on public.destinations using gin (name extensions.gin_trgm_ops);
create trigger trg_destinations_updated before update on public.destinations
  for each row execute function public.set_updated_at();

create table public.user_preferences (
  preference_id             integer generated by default as identity primary key,
  user_id                   integer not null unique references public.users(user_id) on delete cascade,
  language                  text default 'en',
  theme                     text default 'light',
  notifications_enabled     boolean not null default true,
  weather_alerts            boolean not null default true,
  traffic_alerts            boolean not null default true,
  emergency_sharing_enabled boolean not null default true,
  preferred_categories      jsonb,
  updated_at                timestamptz
);
create trigger trg_user_preferences_updated before update on public.user_preferences
  for each row execute function public.set_updated_at();

create table public.weather_cache (
  cache_id     integer generated by default as identity primary key,
  latitude     numeric(10,8) not null,
  longitude    numeric(11,8) not null,
  weather_data jsonb not null,
  expires_at   timestamptz not null,
  created_at   timestamptz not null default now(),
  unique (latitude, longitude)
);
create index idx_weather_expires on public.weather_cache (expires_at);

-- ============================================================================
-- Bookings
-- ============================================================================

create table public.tour_packages (
  package_id       integer generated by default as identity primary key,
  title            text not null,
  description      text,
  duration_days    integer not null default 3,
  total_price      numeric(12,2) not null default 0,
  price_per_day    numeric(10,2) not null default 50.00,
  category         text not null default 'General',
  destinations     jsonb not null default '[]'::jsonb,
  itinerary        jsonb not null default '[]'::jsonb,
  max_travelers    integer not null default 10,
  includes         jsonb not null default '[]'::jsonb,
  image_url        text,
  is_active        boolean not null default true,
  is_ai_generated  boolean not null default false,
  created_by_admin integer,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz
);
create index idx_pkg_price    on public.tour_packages (total_price);
create index idx_pkg_duration on public.tour_packages (duration_days);
create index idx_pkg_category on public.tour_packages (category);
create index idx_pkg_active   on public.tour_packages (is_active);
create trigger trg_tour_packages_updated before update on public.tour_packages
  for each row execute function public.set_updated_at();

create table public.bookings (
  booking_id              integer generated by default as identity primary key,
  user_id                 integer not null references public.users(user_id) on delete cascade,
  -- nullable: hotel / restaurant bookings have no destination (see migration_v14)
  destination_id          integer references public.destinations(destination_id) on delete set null,
  booking_type            text not null default 'single',
  booking_date            date,
  travel_date             date,
  num_travelers           integer not null default 1 check (num_travelers > 0),
  package_id              integer references public.tour_packages(package_id) on delete set null,
  estimated_duration_days integer not null default 1,
  total_amount            numeric(10,2) not null default 0 check (total_amount >= 0),
  notes                   text,
  status                  text not null default 'Pending'
                          check (status in ('Pending','Awaiting Payment','Confirmed','Active','Completed','Cancelled','Refunded')),
  payment_status          text not null default 'Unpaid' check (payment_status in ('Unpaid','Paid','Refunded')),
  payment_intent_id       text,
  cancelled_at            timestamptz,
  cancellation_reason     text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz
);
create index idx_booking_user_status   on public.bookings (user_id, status);
create index idx_booking_destination   on public.bookings (destination_id);
create index idx_booking_status        on public.bookings (status);
create index idx_booking_payment       on public.bookings (payment_status);
create index idx_booking_travel_date   on public.bookings (travel_date);
create index idx_booking_created       on public.bookings (created_at desc);
create index idx_booking_package       on public.bookings (package_id);
create trigger trg_bookings_updated before update on public.bookings
  for each row execute function public.set_updated_at();

create table public.group_bookings (
  group_booking_id integer generated by default as identity primary key,
  trip_name        text not null,
  created_by       integer not null references public.users(user_id) on delete cascade,
  description      text,
  max_members      integer not null default 20 check (max_members > 0),
  destination_id   integer references public.destinations(destination_id) on delete set null,
  total_amount     numeric(10,2) not null default 0,
  payment_type     text not null default 'individual' check (payment_type in ('individual','full')),
  start_date       date,
  end_date         date,
  invite_code      text unique,
  status           text not null default 'Planning'
                   check (status in ('Planning','Open','Full','Active','Completed','Cancelled')),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz
);
create index idx_gb_created_by on public.group_bookings (created_by);
create index idx_gb_status     on public.group_bookings (status);
create index idx_gb_dates      on public.group_bookings (start_date, end_date);
create index idx_gb_destination on public.group_bookings (destination_id);
create trigger trg_group_bookings_updated before update on public.group_bookings
  for each row execute function public.set_updated_at();

create table public.group_booking_members (
  id               integer generated by default as identity primary key,
  group_booking_id integer not null references public.group_bookings(group_booking_id) on delete cascade,
  user_id          integer not null references public.users(user_id) on delete cascade,
  role             text not null default 'member' check (role in ('organizer','member')),
  joined_at        timestamptz not null default now(),
  unique (group_booking_id, user_id)
);
create index idx_gbm_user on public.group_booking_members (user_id);

create table public.group_invitations (
  id               integer generated by default as identity primary key,
  group_booking_id integer not null references public.group_bookings(group_booking_id) on delete cascade,
  sender_id        integer not null references public.users(user_id) on delete cascade,
  receiver_id      integer not null references public.users(user_id) on delete cascade,
  status           text not null default 'Pending' check (status in ('Pending','Accepted','Declined')),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz
);
create index idx_ginv_receiver on public.group_invitations (receiver_id, status);
create index idx_ginv_sender   on public.group_invitations (sender_id);
create index idx_ginv_group    on public.group_invitations (group_booking_id);
-- one open invitation per (trip, receiver) — mirrors the old ER_DUP_ENTRY guard
create unique index uq_ginv_pending on public.group_invitations (group_booking_id, receiver_id)
  where status = 'Pending';
create trigger trg_group_invitations_updated before update on public.group_invitations
  for each row execute function public.set_updated_at();

create table public.group_chat_messages (
  message_id       integer generated by default as identity primary key,
  group_booking_id integer not null references public.group_bookings(group_booking_id) on delete cascade,
  user_id          integer not null references public.users(user_id) on delete cascade,
  message          text not null check (length(message) between 1 and 4000),
  message_type     text not null default 'text' check (message_type in ('text','image','location','system')),
  created_at       timestamptz not null default now()
);
create index idx_gcm_group_time on public.group_chat_messages (group_booking_id, created_at desc);
create index idx_gcm_user       on public.group_chat_messages (user_id);

create table public.group_tracking_sessions (
  id               integer generated by default as identity primary key,
  group_booking_id integer not null references public.group_bookings(group_booking_id) on delete cascade,
  status           text not null default 'active' check (status in ('active','ended')),
  started_at       timestamptz not null default now(),
  ended_at         timestamptz
);
create index idx_gts_group_status on public.group_tracking_sessions (group_booking_id, status);

-- ============================================================================
-- Payments
-- ============================================================================

create table public.payments (
  id                       integer generated by default as identity primary key,
  user_id                  integer not null references public.users(user_id) on delete cascade,
  booking_id               integer references public.bookings(booking_id) on delete set null,
  group_booking_id         integer references public.group_bookings(group_booking_id) on delete set null,
  stripe_payment_intent_id text unique,
  amount                   numeric(10,2) not null,
  currency                 text not null default 'usd',
  status                   text not null default 'pending' check (status in ('pending','succeeded','failed','refunded')),
  refund_requested_at      timestamptz,
  refund_approved_at       timestamptz,
  refund_rejected_at       timestamptz,
  refund_admin_notes       text,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz
);
create index idx_pay_user     on public.payments (user_id);
create index idx_pay_booking  on public.payments (booking_id);
create index idx_pay_group    on public.payments (group_booking_id);
create index idx_pay_status   on public.payments (status);
create index idx_pay_created  on public.payments (created_at desc);
create index idx_pay_refund   on public.payments (refund_requested_at);
create trigger trg_payments_updated before update on public.payments
  for each row execute function public.set_updated_at();

create table public.transactions (
  id                    integer generated by default as identity primary key,
  payment_id            integer not null references public.payments(id) on delete cascade,
  amount                numeric(10,2) not null,
  status                text not null default 'pending' check (status in ('pending','completed','failed','refunded')),
  transaction_reference text,
  created_at            timestamptz not null default now()
);
create index idx_txn_payment   on public.transactions (payment_id);
create index idx_txn_reference on public.transactions (transaction_reference);

-- ============================================================================
-- Routes, wishlist, reviews
-- ============================================================================

create table public.routes (
  route_id           integer generated by default as identity primary key,
  user_id            integer not null references public.users(user_id) on delete cascade,
  route_name         text not null,
  description        text,
  start_location     text,
  end_location       text,
  start_lat          numeric(10,8),
  start_lng          numeric(11,8),
  end_lat            numeric(10,8),
  end_lng            numeric(11,8),
  total_distance     numeric(10,2),
  estimated_duration integer,
  route_data         jsonb,
  difficulty_level   text,
  weather_optimized  boolean default false,
  traffic_considered boolean default false,
  is_public          boolean not null default false,
  views_count        integer not null default 0,
  rating             numeric(3,2),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz
);
create index idx_route_user_created on public.routes (user_id, created_at desc);
create index idx_route_public       on public.routes (is_public) where is_public;
create trigger trg_routes_updated before update on public.routes
  for each row execute function public.set_updated_at();

create table public.route_stops (
  stop_id          integer generated by default as identity primary key,
  route_id         integer not null references public.routes(route_id) on delete cascade,
  destination_id   integer references public.destinations(destination_id) on delete set null,
  stop_order       integer not null default 0,
  latitude         numeric(10,8),
  longitude        numeric(11,8),
  stop_name        text,
  duration_at_stop integer,
  notes            text,
  created_at       timestamptz not null default now()
);
create index idx_rstop_route on public.route_stops (route_id, stop_order);
create index idx_rstop_dest  on public.route_stops (destination_id);

create table public.wishlists (
  wishlist_id        integer generated by default as identity primary key,
  user_id            integer not null references public.users(user_id) on delete cascade,
  destination_id     integer not null references public.destinations(destination_id) on delete cascade,
  notes              text,
  priority           text,
  planned_visit_date date,
  created_at         timestamptz not null default now(),
  unique (user_id, destination_id)
);
create index idx_wl_destination on public.wishlists (destination_id);

create table public.reviews (
  review_id      integer generated by default as identity primary key,
  user_id        integer not null references public.users(user_id) on delete cascade,
  destination_id integer references public.destinations(destination_id) on delete cascade,
  route_id       integer references public.routes(route_id) on delete cascade,
  rating         integer not null check (rating between 1 and 5),
  title          text,
  review_text    text,
  images         jsonb,
  helpful_count  integer not null default 0,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz
);
create index idx_rev_dest  on public.reviews (destination_id);
create index idx_rev_user  on public.reviews (user_id);
create index idx_rev_route on public.reviews (route_id);
create trigger trg_reviews_updated before update on public.reviews
  for each row execute function public.set_updated_at();

create table public.budget_plans (
  plan_id        integer generated by default as identity primary key,
  user_id        integer not null references public.users(user_id) on delete cascade,
  budget_amount  numeric(12,2) not null,
  num_travelers  integer not null default 1,
  duration_days  integer not null default 3,
  start_city     text,
  preferences    text,
  generated_plan jsonb,
  created_at     timestamptz not null default now()
);
create index idx_bp_user on public.budget_plans (user_id, created_at desc);

-- ============================================================================
-- Emergency
-- ============================================================================

create table public.emergency_contacts (
  contact_id    integer generated by default as identity primary key,
  user_id       integer not null references public.users(user_id) on delete cascade,
  contact_name  text not null,
  contact_phone text not null,
  contact_email text,
  relationship  text,
  is_primary    boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz
);
create index idx_ec_user on public.emergency_contacts (user_id);
create trigger trg_emergency_contacts_updated before update on public.emergency_contacts
  for each row execute function public.set_updated_at();

create table public.emergency_alerts (
  id                integer generated by default as identity primary key,
  user_id           integer not null references public.users(user_id) on delete cascade,
  trip_id           integer,
  trip_type         text check (trip_type in ('single','group')),
  latitude          numeric(10,8) not null default 0,
  longitude         numeric(11,8) not null default 0,
  message           text,
  status            text not null default 'Active' check (status in ('Active','Acknowledged','Resolved','Cancelled')),
  workflow_status   text not null default 'New' check (workflow_status in ('New','Acknowledged','In Progress','Resolved')),
  resolution_notes  text,
  acknowledged_at   timestamptz,
  in_progress_at    timestamptz,
  assigned_admin_id integer,
  resolved_at       timestamptz,
  created_at        timestamptz not null default now()
);
create index idx_ea_user_status on public.emergency_alerts (user_id, status);
create index idx_ea_status      on public.emergency_alerts (status);
create index idx_ea_created     on public.emergency_alerts (created_at desc);

-- legacy alternate SOS table (still used by /sos routes + admin "sos-alerts")
create table public.sos_alerts (
  id                integer generated by default as identity primary key,
  user_id           integer not null references public.users(user_id) on delete cascade,
  latitude          numeric(10,8),
  longitude         numeric(11,8),
  message           text,
  status            text not null default 'Active' check (status in ('Active','Resolved','Cancelled')),
  workflow_status   text not null default 'New' check (workflow_status in ('New','Acknowledged','In Progress','Resolved')),
  resolution_notes  text,
  assigned_admin_id integer,
  created_at        timestamptz not null default now(),
  resolved_at       timestamptz
);
create index idx_sos_user   on public.sos_alerts (user_id);
create index idx_sos_status on public.sos_alerts (status);

create table public.emergency_events (
  id         integer generated by default as identity primary key,
  user_id    integer not null references public.users(user_id) on delete cascade,
  type       text not null check (type in ('ambulance','police','tourist_police','ice_share','full_sos')),
  latitude   numeric(10,8),
  longitude  numeric(11,8),
  status     text not null default 'Pending' check (status in ('Pending','Acknowledged')),
  created_at timestamptz not null default now()
);
create index idx_ee_user    on public.emergency_events (user_id);
create index idx_ee_created on public.emergency_events (created_at desc);

create table public.emergency_tracking (
  id           integer generated by default as identity primary key,
  emergency_id integer not null references public.emergency_alerts(id) on delete cascade,
  latitude     numeric(10,8) not null,
  longitude    numeric(11,8) not null,
  "timestamp"  timestamptz not null default now()
);
create index idx_et_emergency on public.emergency_tracking (emergency_id, "timestamp");

-- ============================================================================
-- Notifications & location
-- ============================================================================

create table public.notifications (
  notification_id        integer generated by default as identity primary key,
  user_id                integer not null references public.users(user_id) on delete cascade,
  title                  text not null,
  message                text not null,
  type                   text not null default 'general',
  related_route_id       integer references public.routes(route_id) on delete set null,
  related_destination_id integer references public.destinations(destination_id) on delete set null,
  action_url             text,
  is_read                boolean not null default false,
  created_at             timestamptz not null default now()
);
create index idx_notif_user_unread on public.notifications (user_id, is_read, created_at desc);
create index idx_notif_route       on public.notifications (related_route_id);
create index idx_notif_dest        on public.notifications (related_destination_id);

create table public.fcm_tokens (
  id         integer generated by default as identity primary key,
  user_id    integer not null references public.users(user_id) on delete cascade,
  token      text not null unique,
  platform   text not null default 'android' check (platform in ('android','ios','web')),
  created_at timestamptz not null default now(),
  updated_at timestamptz
);
create index idx_fcm_user on public.fcm_tokens (user_id);

create table public.user_location_updates (
  location_update_id integer generated by default as identity primary key,
  user_identifier    text,
  latitude           numeric(10,8) not null check (latitude between -90 and 90),
  longitude          numeric(11,8) not null check (longitude between -180 and 180),
  city               text,
  country            text,
  accuracy_meters    numeric(10,2),
  captured_at        timestamptz not null,
  created_at         timestamptz not null default now()
);
create index idx_loc_user_captured on public.user_location_updates (user_identifier, captured_at desc);

-- ============================================================================
-- AI
-- ============================================================================

create table public.ai_chat_history (
  chat_id        integer generated by default as identity primary key,
  user_id        integer not null references public.users(user_id) on delete cascade,
  user_message   text not null,
  ai_response    text not null,
  context_data   jsonb,
  helpful_rating integer check (helpful_rating between 1 and 5),
  created_at     timestamptz not null default now()
);
create index idx_ai_user_created on public.ai_chat_history (user_id, created_at desc);

create table public.mental_health_chat_history (
  id           integer generated by default as identity primary key,
  user_id      integer not null references public.users(user_id) on delete cascade,
  user_message text not null,
  ai_response  text not null,
  created_at   timestamptz not null default now()
);
create index idx_mh_user_time on public.mental_health_chat_history (user_id, created_at);

create table public.ai_recommendations (
  recommendation_id      integer generated by default as identity primary key,
  user_id                integer not null references public.users(user_id) on delete cascade,
  destination_id         integer references public.destinations(destination_id) on delete cascade,
  title                  text,
  reason                 text,
  category               text,
  confidence_score       numeric(3,2),
  recommended_visit_date date,
  viewed                 boolean not null default false,
  helpful_rating         integer,
  created_at             timestamptz not null default now()
);
create index idx_airec_user on public.ai_recommendations (user_id, viewed);
create index idx_airec_dest on public.ai_recommendations (destination_id);

-- ============================================================================
-- Virtual tours
-- ============================================================================

create table public.virtual_tours (
  id             integer generated by default as identity primary key,
  destination_id integer references public.destinations(destination_id) on delete set null,
  title          text not null,
  description    text,
  thumbnail_url  text,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz
);
create index idx_vt_active_dest on public.virtual_tours (is_active, destination_id);
create index idx_vt_destination on public.virtual_tours (destination_id);
create trigger trg_virtual_tours_updated before update on public.virtual_tours
  for each row execute function public.set_updated_at();

create table public.virtual_tour_scenes (
  id            integer generated by default as identity primary key,
  tour_id       integer not null references public.virtual_tours(id) on delete cascade,
  scene_name    text not null,
  panorama_url  text not null,
  thumbnail_url text,
  description   text,
  ai_narration  text,
  scene_order   integer not null default 0
);
create index idx_vts_tour on public.virtual_tour_scenes (tour_id, scene_order);

create table public.virtual_tour_hotspots (
  id              integer generated by default as identity primary key,
  scene_id        integer not null references public.virtual_tour_scenes(id) on delete cascade,
  type            text not null default 'info' check (type in ('scene','info')),
  target_scene_id integer references public.virtual_tour_scenes(id) on delete set null,
  title           text,
  text            text,
  pitch           double precision not null default 0,
  yaw             double precision not null default 0
);
create index idx_vth_scene  on public.virtual_tour_hotspots (scene_id);
create index idx_vth_target on public.virtual_tour_hotspots (target_scene_id);

-- ============================================================================
-- Admin logs
-- ============================================================================

create table public.admin_activity_logs (
  id          integer generated by default as identity primary key,
  admin_id    integer not null,
  admin_name  text not null default '',
  action      text not null,
  target_type text,
  target_id   integer,
  details     text,
  ip_address  text,
  created_at  timestamptz not null default now()
);
create index idx_aal_created on public.admin_activity_logs (created_at desc);
create index idx_aal_action  on public.admin_activity_logs (action);

create table public.admin_logs (
  log_id      integer generated by default as identity primary key,
  admin_id    integer not null references public.users(user_id) on delete cascade,
  action      text not null,
  target_type text,
  target_id   integer,
  details     jsonb,
  ip_address  text,
  created_at  timestamptz not null default now()
);
create index idx_alog_admin on public.admin_logs (admin_id, created_at);
